Patch.legal.source:
def legal(s, t):
    cen = sum(t[1:]) / 3
    for u in s.tris:
        if abs(u[1] - cen) < 3 * SCALE_LEN and (inside(cen, *u[1:]) or any(inside(z, *u[1:]) for z in t[1:])):
            return False
    if canon(t) in {canon(u) for u in s.edges.get(frozenset((key(t[1]), key(t[2]))), [])}:
        return False
    return all(s.vertex_ok(k, v) for k, v in corners([t]).items())

Patch.vertex_ok.source:
def vertex_ok_fixed(s, k, extra):
    """Corrected version of laying_the_tiling.Patch.vertex_ok. The original wraps each gap between
    consecutive corners into (-pi, pi], so a gap WIDER than pi (common around holes) was misread as an
    overlap and a legal partial star was rejected. Here gaps are measured linearly along the sorted start
    angles, with one explicit wrap-around gap; arcs and complete stars are then checked exactly as before."""
    lst = sorted(s.V[k] + extra); n = len(lst)
    tot = sum(d for _, d, _ in lst)
    if tot > 2 * math.pi + 1e-6:
        return False
    if abs(tot - 2 * math.pi) < 1e-6:
        return L.star(lst) in L.STARS
    gaps = [lst[i][0] - (lst[i - 1][0] + lst[i - 1][1]) for i in range(1, n)]
    gaps = [lst[0][0] + 2 * math.pi - (lst[-1][0] + lst[-1][1])] + gaps      # gaps[i] = gap before lst[i]
    if any(g < -1e-6 for g in gaps):
        return False                                     # genuinely overlapping corners
    start = next((i for i in range(n) if gaps[i] > 1e-6), None)
    if start is None:
        return False
    seq = lst[start:] + lst[:start]; gs = gaps[start:] + gaps[:start]; arcs = [[seq[0]]]
    for i in range(1, n):
        if gs[i] > 1e-6:
            arcs.append([seq[i]])
        else:
            arcs[-1].append(seq[i])
    return all(tuple(l for _, _, l in arc) in L.ARCS for arc in arcs)

D.candidates.source:
def candidates(P, p, q, r):
    """Patch.candidates, but keeping BOTH decorations of a tile position. laying_the_tiling's version keys its output
    by canon(), which ignores the A/B/C roles, so the two mirror decorations of an isosceles half-tile at the same place
    collapse to one (see PREREGISTRATION.md, changes before the first run)."""
    out = {}
    for (c, o), (tc, A, B, C) in L.TEMPL.items():
        Pp = {"A": A, "B": B, "C": C}
        for X, Y, Z in (("A", "B", "C"), ("B", "C", "A"), ("C", "A", "B"), ("B", "A", "C"), ("C", "B", "A"), ("A", "C", "B")):
            x, y, z = Pp[X], Pp[Y], Pp[Z]
            if abs(abs(y - x) - abs(q - p)) > 1e-6:
                continue
            a = (q - p) / (y - x); zz = p + a * (z - x)
            if L.orient(p, q, zz) * L.orient(p, q, r) >= 0:
                continue
            img = {X: p, Y: q, Z: zz}; nt = (tc, img["A"], img["B"], img["C"])
            if P.legal(nt):
                out[dkey(nt)] = nt
    return list(out.values())

patient_scar.source:
def patient_scar(P, rng, scars, verify_legal=True):
    """One scar-tolerant slice. `scars` (set of pinned edge-keys) is mutated.
    Returns (status, n_placed, kind, newly_pinned_list, illegal_count).
    status in {'ok','total_arrest'}."""
    fr = P.frontier()
    forced = {}
    growable = []
    newly = []
    illegal = 0
    for e in fr:
        ek = ekey(e[0], e[1])
        if ek in scars:
            continue
        cs = D.candidates(P, *e[:3])
        if not cs:
            scars.add(ek); newly.append(ek); continue
        growable.append((e, cs))
        if len(cs) == 1:
            forced.setdefault(D.dkey(cs[0]), cs[0])
    if not growable:
        return "total_arrest", 0, None, newly, illegal
    if forced:
        n = 0
        for t in forced.values():
            if P.legal(t):
                P.add(t); n += 1
            elif verify_legal:
                pass  # a forced candidate made illegal by a sibling placement is simply skipped (baseline behaviour)
        return "ok", n, "forced", newly, illegal
    e0, cs0 = growable[0]
    t = rng.choice(ordered(cs0))
    if verify_legal and not P.legal(t):
        illegal += 1            # must never happen: candidates come from D.candidates (legal by construction)
    P.add(t)
    return "ok", 1, "guess", newly, illegal
